<template><div><h3>Included service usage</h3><el-table :data="wallet.includedUsage||[]" border><el-table-column prop="serviceId" label="Service"/><el-table-column prop="amount" label="Included"/><el-table-column prop="used" label="Used"/><el-table-column prop="reserved" label="Reserved"/><el-table-column prop="remaining" label="Available"/><el-table-column label="Resets"><template slot-scope="s">{{ dateTime(s.row.resetAt) }}</template></el-table-column></el-table><h3>Credit wallets</h3><el-table :data="(wallet.accounts||[]).filter(account=>!account.future||wallet.batches.some(batch=>batch.creditType===account.code))" border data-testid="typed-wallets"><el-table-column prop="name" label="Credit Type"/><el-table-column prop="available" label="Available"/><el-table-column prop="purchased" label="Purchased"/><el-table-column prop="reserved" label="Reserved"/></el-table><p class="field-help">Balances are independent by credit type. Legacy Credits retain their original use; no automatic conversion or shared total.</p><h3>Legacy Credits balance</h3><div class="wallet-metrics"><div><span>Available</span><strong>{{ wallet.available }}</strong></div><div><span>Reserved</span><strong>{{ wallet.reserved }}</strong></div><div><span>Next Expiry</span><strong class="small-metric">{{ dateTime(nextExpiry) }}</strong></div><el-button type="primary" @click="visible=true">Issue Compensation</el-button></div><el-table :data="wallet.batches" row-key="id" border><el-table-column label="Batch / Source" min-width="245"><template slot-scope="s"><strong>{{ s.row.source }}</strong><div class="item-code">{{ s.row.id }}</div></template></el-table-column><el-table-column label="Credit Type" min-width="170"><template slot-scope="s">{{ creditTypeLabel(s.row.creditType) }}</template></el-table-column><el-table-column prop="original" label="Issued" width="90"/><el-table-column prop="remaining" label="Remaining" width="100"/><el-table-column prop="reserved" label="Reserved" width="95"/><el-table-column prop="available" label="Available" width="95"/><el-table-column label="Expires" min-width="180"><template slot-scope="s">{{ s.row.neverExpires ? "Never expires" : dateTime(s.row.expiresAt) }}</template></el-table-column><el-table-column prop="status" label="Status" width="95"/></el-table><p class="field-help">Ordered by expiry. Availability excludes reservations and expired batches. New purchased Credits never expire. Legacy batches retain their original dates. Included actions are separate from this wallet.</p><template v-if="wallet.scheduled && wallet.scheduled.length"><h3>Scheduled benefit issues</h3><el-table :data="wallet.scheduled" border><el-table-column label="Due" min-width="180"><template slot-scope="s">{{ dateTime(s.row.dueAt) }}</template></el-table-column><el-table-column label="Credit Type"><template slot-scope="s">{{ creditTypeLabel(s.row.benefit.creditType) }}</template></el-table-column><el-table-column prop="benefit.amount" label="Credits"/><el-table-column label="Expiration"><template slot-scope="s">{{ s.row.benefit.expirationTime?dateTime(s.row.benefit.expirationTime):s.row.benefit.expiration==='never'?'Never expires':s.row.benefit.validityDays+' days' }}</template></el-table-column><el-table-column prop="status" label="Status"/></el-table></template><el-dialog title="Credits Compensation" :visible.sync="visible" width="520px" :close-on-click-modal="false"><el-form label-width="120px" :disabled="busy"><el-form-item label="Credit Type"><el-select v-model="creditType"><el-option v-for="type in types" :key="type" :label="creditTypeLabel(type)" :value="type"/></el-select></el-form-item><el-form-item label="Credits"><admin-number v-model="amount" :min="1" :max="1000000" :precision="0"/></el-form-item><el-form-item label="Validity Days"><admin-number v-model="validityDays" :min="1" :max="3650" :precision="0"/></el-form-item><el-form-item label="Reason"><el-input v-model.trim="reason" type="textarea" maxlength="500"/></el-form-item></el-form><p class="field-help">Creates a separate batch. Never edits a purchased batch or reverses its original ledger.</p><span slot="footer"><el-button @click="visible=false">Cancel</el-button><el-button type="primary" :loading="busy" :disabled="reason.length<3" @click="issue">Confirm Issue</el-button></span></el-dialog></div></template>
<script>
import AdminNumber from '@/components/AdminNumber'
import {creditTypeLabel} from '@/utils/entitlements'
import {compensate,requestKey} from '@/api/commerce'
import {dateTime} from '@/utils/format'
export default{components:{AdminNumber},props:{wallet:Object,userId:String},data(){return{visible:false,busy:false,creditType:'AI_COACH_CREDIT',types:['AI_COACH_CREDIT','CONTENT_CREDIT','LEGACY_CREDIT'],amount:10,validityDays:30,reason:'',attempt:null}},computed:{nextExpiry(){const batch=this.wallet.batches.find(b=>b.available>0 && b.expiresAt);return batch?batch.expiresAt:null}},methods:{dateTime,creditTypeLabel,async issue(){const input={userId:this.userId,creditType:this.creditType,amount:this.amount,validityDays:this.validityDays,reason:this.reason};const fingerprint=JSON.stringify(input);if(!this.attempt||this.attempt.fingerprint!==fingerprint)this.attempt={fingerprint,key:requestKey()};this.busy=true;try{await compensate({...input,requestKey:this.attempt.key});this.visible=false;this.$message.success('Compensation batch issued.');this.$emit('changed')}catch(_){}finally{this.busy=false}}}}
</script>
